extern "C" void __wrap_glGetShaderSource(GLuint shader, GLsizei bufSize,
                                         GLsizei* length, GLchar* source) {
    if (gfxNullActive()) {
        gfxNoteVoidCall();
        size_t have = 0;
        const char* recorded = gfxShaderSource(shader, &have);
        if (recorded == nullptr) {
            if (length != nullptr) {
                *length = 0;
            }
            if (source != nullptr && bufSize > 0) {
                source[0] = '\0';
            }
            return;
        }
        const size_t copy = bufSize > 0 && have > static_cast<size_t>(bufSize)
                                ? static_cast<size_t>(bufSize - 1)
                                : have;
        if (source != nullptr && bufSize > 0) {
            std::memcpy(source, recorded, copy);
            source[copy] = '\0';
        }
        if (length != nullptr) {
            *length = static_cast<GLsizei>(copy);
        }
        return;
    }
    __real_glGetShaderSource(shader, bufSize, length, source);
}

