extern "C" void __wrap_glGetIntegerv(GLenum pname, GLint* data) {
    if (gfxNullActive()) {
        gfxNoteVoidCall();
        if (data == nullptr) {
            return;
        }
        switch (pname) {
        // Bindings: truthfully "none".
        case GL_ARRAY_BUFFER_BINDING:
        case GL_ELEMENT_ARRAY_BUFFER_BINDING:
        case GL_FRAMEBUFFER_BINDING:
        case GL_RENDERBUFFER_BINDING:
        case GL_CURRENT_PROGRAM:
        case GL_TEXTURE_BINDING_2D:
        case GL_TEXTURE_BINDING_CUBE_MAP:
            *data = 0;
            break;
        case GL_ACTIVE_TEXTURE:
            *data = GL_TEXTURE0;
            break;
        // ES3 pnames the engine can still ask for by number. Kept as literals:
        // devkitPro's ES2 headers do not name them.
        case 0x8893: // GL_ARRAY_BUFFER_SIZE
        case 0x8898: // GL_ELEMENT_ARRAY_BUFFER_SIZE
            *data = static_cast<GLint>(s_bufferBoundSize);
            break;
        case 0x8CDF: // GL_MAX_COLOR_ATTACHMENTS
            *data = 1;
            break;
        case 0x80E8: // GL_MAX_ELEMENTS_VERTICES
        case 0x80E9: // GL_MAX_ELEMENTS_INDICES
            *data = 65535;
            break;
        case 0x80A9: // GL_SAMPLES
        case 0x80A8: // GL_SAMPLE_BUFFERS
        case 0x8D57: // GL_MAX_SAMPLES
        case 0x821D: // GL_NUM_EXTENSIONS
            *data = 0;
            break;
        // Limits. A 0 here is a divide-by-zero in guest code, so every size,
        // count and bit-field answer is non-zero.
        case GL_MAX_TEXTURE_SIZE:
        case GL_MAX_CUBE_MAP_TEXTURE_SIZE:
        case GL_MAX_RENDERBUFFER_SIZE:
            *data = 4096;
            break;
        case GL_MAX_VERTEX_ATTRIBS:
        case GL_MAX_VARYING_VECTORS:
        case GL_MAX_VERTEX_TEXTURE_IMAGE_UNITS:
            *data = 8;
            break;
        case GL_MAX_TEXTURE_IMAGE_UNITS:
        case GL_MAX_COMBINED_TEXTURE_IMAGE_UNITS:
            *data = 16;
            break;
        case GL_MAX_VERTEX_UNIFORM_VECTORS:
        case GL_MAX_FRAGMENT_UNIFORM_VECTORS:
            *data = 256;
            break;
        case GL_RED_BITS:
        case GL_GREEN_BITS:
        case GL_BLUE_BITS:
        case GL_ALPHA_BITS:
        case GL_STENCIL_BITS:
            *data = 8;
            break;
        case GL_DEPTH_BITS:
            *data = 24;
            break;
        case GL_SUBPIXEL_BITS:
            *data = 4;
            break;
        case GL_UNPACK_ALIGNMENT:
        case GL_PACK_ALIGNMENT:
            *data = 4;
            break;        case GL_IMPLEMENTATION_COLOR_READ_FORMAT:
            *data = GL_RGBA;
            break;
        case GL_IMPLEMENTATION_COLOR_READ_TYPE:
            *data = GL_UNSIGNED_BYTE;
            break;
        case GL_VIEWPORT:
            fillInts(data, 4, 0);
            data[2] = 1280;
            data[3] = 720;
            break;
        case GL_SCISSOR_BOX:
            fillInts(data, 4, 0);
            data[2] = 1280;
            data[3] = 720;
            break;
        case GL_MAX_VIEWPORT_DIMS:
            fillInts(data, 2, 0);
            data[0] = 4096;
            data[1] = 4096;
            break;
        default:
            // Unlisted: 1 rather than 0. A zero is the one answer that can
            // take the guest down (division) or hand back a null handle.
            *data = 1;
            break;
        }
        return;
    }
    __real_glGetIntegerv(pname, data);
}

