constexpr size_t kExtraProcCount = sizeof(kExtraProcs) / sizeof(kExtraProcs[0]);

// The generated half. It opens with a declaration for every one of the 171
// wrapped symbols -- taken from the devkitPro headers -- so the proc table
// below has something to point at, and so a hand-written wrapper that drifts
// from its header signature is a compile error. Its own definitions come
// after the hand-written ones, and the two sets are disjoint.
#include "gfx_gl_generated.inc"

#include "gfx_proctable.inc"

// NOT included: gfx_symbol_exports.inc.
//
// The idea was sound and the mechanism is structurally impossible as written.
// -Wl,--wrap=X does not create a second entry point; it makes the linker ALIAS
// __real_X to X. So the moment this file defines X itself, __real_X resolves to
// our own forwarder and the wrapper recurses forever:
//
//     __wrap_glClear -> __real_glClear -> glClear (ours)
//                      -> __wrap_glClear -> ...
//
// Measured, both variants of the attempt:
//   mesa4  exported gl* AND egl*  -> wedged at the process's first EGL call,
//                                   "view-egl-probe-begin", threads=1,
//                                   total_imports=385
//   mesa5  exported gl* only      -> EGL ladder completed, then wedged before
//                                   the frame loop: threads=1, imports=385,
//                                   gfx-stats count=0
//
// The generator (tools/gen_gfx_symbol_exports.py) and its output are kept so
// the next attempt starts from a measured baseline. Any real version must DROP
// --wrap for the symbols it owns and reach the driver some other way --
// dlsym(RTLD_NEXT, "glClear") is the obvious candidate, and it is untested.

// Probe only: does WE wrap this name? Returns nullptr when we do not, and
// deliberately does NOT record an unknown-proc event -- a name we simply do
// not wrap is not a gap worth logging, and the caller falls back to the
// driver's own pointer.
//
// Needed because gfxProcAddress() below can never return null: it hands back a
// stub for anything it does not wrap. Asking it "do you own this?" therefore
// gets a non-null answer every time, which is exactly how eglGetProcAddress
// ended up bypassing every counter on the Mesa path.
void* gfxProcAddressIfWrapped(const char* name) {
    if (name == nullptr || name[0] == '\0') {
        return nullptr;
    }
    for (size_t i = 0; i < kWrapProcCount; ++i) {
        if (std::strcmp(kWrapProcs[i].name, name) == 0) {
            return kWrapProcs[i].address;
        }
    }
    for (size_t i = 0; i < kExtraProcCount; ++i) {
        if (std::strcmp(kExtraProcs[i].name, name) == 0) {
            return kExtraProcs[i].address;
        }
    }
    return nullptr;
}

void* gfxProcAddress(const char* name) {
    if (name == nullptr || name[0] == '\0') {
        return reinterpret_cast<void*>(&gfxGenericProcStub);
    }
    for (size_t i = 0; i < kWrapProcCount; ++i) {
        if (std::strcmp(kWrapProcs[i].name, name) == 0) {
            return kWrapProcs[i].address;
        }
    }
    for (size_t i = 0; i < kExtraProcCount; ++i) {
        if (std::strcmp(kExtraProcs[i].name, name) == 0) {
            return kExtraProcs[i].address;
        }
    }
    gfxNoteUnknownProc(name);
    return reinterpret_cast<void*>(&gfxGenericProcStub);
}

